<?php
namespace App\Modules\Counselor\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Counselor\{Services\CommentService,Resources\CommentResource,Requests\StoreCommentRequest,Requests\UpdateCommentRequest};use Illuminate\Http\Request;use Illuminate\Support\Facades\Gate;
class CommentController extends Controller {public function __construct(private CommentService $service){}public function index(Request $r){$f=$r->validate(['type'=>'required|in:counselor','id'=>'required|integer|exists:counselors,id','per_page'=>'sometimes|integer|min:1|max:100']);$f['type']=\App\Modules\Counselor\Models\Counselor::class;$f['approved']=true;return CommentResource::collection($this->service->index($f));}public function store(StoreCommentRequest $r){$data=$r->validated();$data['commentable_type']=\App\Modules\Counselor\Models\Counselor::class;$data['commentable_id']=$data['id'];unset($data['id'],$data['type']);if(isset($data['parent_id'])){$p=$this->service->find($data['parent_id']);abort_unless($p && $p->commentable_type===$data['commentable_type'] && (int)$p->commentable_id===(int)$data['commentable_id'],422);} $data['user_id']=$r->user()->id;return (new CommentResource($this->service->create($data)))->response()->setStatusCode(201);}public function update(UpdateCommentRequest $r,int $comment){$m=$this->service->find($comment)??abort(404);return new CommentResource($this->service->update($m,$r->validated()));}public function destroy(int $comment){$m=$this->service->find($comment)??abort(404);Gate::authorize('delete',$m);$this->service->delete($m);return response()->noContent();}}
